for (i = 0; i < ncerts; i++) {
                                size_t s = 0;

                                ret =
                                    gnutls_x509_crt_print(certs[i],
                                                          GNUTLS_CRT_PRINT_FULL,
                                                          &out);
                                if (ret < 0)
                                        addf(str, "error: crt_print: %s\n",
                                             gnutls_strerror(ret));
                                else {
                                        addf(str, "%.*s", out.size,
                                             out.data);
                                        gnutls_free(out.data);
                                }

                                ret =
                                    gnutls_x509_crt_export(certs[i],
                                                           GNUTLS_X509_FMT_PEM,
                                                           NULL, &s);
                                if (ret != GNUTLS_E_SHORT_MEMORY_BUFFER)
                                        addf(str,
                                             "error: crt_export: %s\n",
                                             gnutls_strerror(ret));
                                else {
                                        out.data = gnutls_malloc(s);
                                        if (out.data == NULL)
                                                addf(str,
                                                     "error: malloc: %s\n",
                                                     gnutls_strerror
                                                     (GNUTLS_E_MEMORY_ERROR));
                                        else {
                                                ret =
                                                    gnutls_x509_crt_export
                                                    (certs[i],
                                                     GNUTLS_X509_FMT_PEM,
                                                     out.data, &s);
                                                if (ret < 0)
                                                        addf(str,
                                                             "error: crt_export: %s\n",
                                                             gnutls_strerror
                                                             (ret));
                                                else {
                                                        out.size = s;
                                                        addf(str, "%.*s",
                                                             out.size,
                                                             out.data);
                                                }
                                                gnutls_free(out.data);
                                        }
                                }

                                gnutls_x509_crt_deinit(certs[i]);
                        }
                        gnutls_free(certs);
                }
        }
